"""Generate UI metadata; --check fails on catalog drift."""

import json
import sys
from pathlib import Path

from backend.app.features.templates.formats import FORMATS

path = (
    Path(__file__).resolve().parents[1]
    / "frontend/src/features/templates/variableFormats.ts"
)
expected = (
    "// Generated by scripts/generate-variable-formats.py; do not edit.\nexport const variableFormats = "
    + json.dumps(FORMATS, indent=2)
    + ";\n"
)
if "--check" in sys.argv:
    if path.read_text() != expected:
        raise SystemExit(
            "Run PYTHONPATH=. .venv/bin/python scripts/generate-variable-formats.py"
        )
else:
    path.write_text(expected)
